package games.pixscape.studio.history.initializer;

import com.artemis.World;
import com.artemis.WorldConfiguration;
import com.badlogic.gdx.math.Vector2;
import games.pixscape.runtime.component.TransformComponent;
import games.pixscape.runtime.component.physics.*;
import games.pixscape.runtime.service.Box2dWorldService;
import games.pixscape.runtime.service.PhysicsService;
import games.pixscape.studio.history.HistoryIdRegistry;
import games.pixscape.studio.history.commands.CreateJointCommand;
import org.junit.Assert;
import org.junit.Test;

public class GenericEntityInitializerPhysicsJointTest {

    @Test public void copiesDistanceJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_DISTANCE); PhysicsDistanceJointComponent c = w.getMapper(PhysicsDistanceJointComponent.class).create(src); c.lengthM = 4.2f; c.frequencyHz = 2.3f; c.dampingRatio = 0.7f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_DISTANCE); Assert.assertTrue(w.getMapper(PhysicsDistanceJointComponent.class).has(clone)); PhysicsDistanceJointComponent out = w.getMapper(PhysicsDistanceJointComponent.class).get(clone); Assert.assertEquals(4.2f, out.lengthM, 0f); Assert.assertEquals(2.3f, out.frequencyHz, 0f); Assert.assertEquals(0.7f, out.dampingRatio, 0f); }
    @Test public void copiesWheelJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_WHEEL); PhysicsWheelJointComponent c = w.getMapper(PhysicsWheelJointComponent.class).create(src); c.axisX = 0.4f; c.axisY = 0.9f; c.enableMotor = true; c.motorSpeedRad = 1.2f; c.maxMotorTorque = 7.8f; c.frequencyHz = 5.5f; c.dampingRatio = 0.6f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_WHEEL); Assert.assertTrue(w.getMapper(PhysicsWheelJointComponent.class).has(clone)); PhysicsWheelJointComponent out = w.getMapper(PhysicsWheelJointComponent.class).get(clone); Assert.assertEquals(0.4f, out.axisX, 0f); Assert.assertEquals(0.9f, out.axisY, 0f); Assert.assertTrue(out.enableMotor); Assert.assertEquals(1.2f, out.motorSpeedRad, 0f); Assert.assertEquals(7.8f, out.maxMotorTorque, 0f); Assert.assertEquals(5.5f, out.frequencyHz, 0f); Assert.assertEquals(0.6f, out.dampingRatio, 0f); }
    @Test public void copiesRevoluteJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_REVOLUTE); PhysicsRevoluteJointComponent c = w.getMapper(PhysicsRevoluteJointComponent.class).create(src); c.enableLimit = true; c.lowerAngleRad = -0.7f; c.upperAngleRad = 0.8f; c.enableMotor = true; c.motorSpeedRad = 3.2f; c.maxMotorTorque = 6.4f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_REVOLUTE); Assert.assertTrue(w.getMapper(PhysicsRevoluteJointComponent.class).has(clone)); PhysicsRevoluteJointComponent out = w.getMapper(PhysicsRevoluteJointComponent.class).get(clone); Assert.assertTrue(out.enableLimit); Assert.assertEquals(-0.7f, out.lowerAngleRad, 0f); Assert.assertEquals(0.8f, out.upperAngleRad, 0f); Assert.assertTrue(out.enableMotor); Assert.assertEquals(3.2f, out.motorSpeedRad, 0f); Assert.assertEquals(6.4f, out.maxMotorTorque, 0f); }
    @Test public void copiesPrismaticJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_PRISMATIC); PhysicsPrismaticJointComponent c = w.getMapper(PhysicsPrismaticJointComponent.class).create(src); c.axisX = 1f; c.axisY = 0f; c.enableLimit = true; c.lowerTranslationM = -2f; c.upperTranslationM = 3f; c.enableMotor = true; c.motorSpeedMps = 1.5f; c.maxMotorForce = 12f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_PRISMATIC); Assert.assertTrue(w.getMapper(PhysicsPrismaticJointComponent.class).has(clone)); PhysicsPrismaticJointComponent out = w.getMapper(PhysicsPrismaticJointComponent.class).get(clone); Assert.assertEquals(1f, out.axisX, 0f); Assert.assertEquals(0f, out.axisY, 0f); Assert.assertTrue(out.enableLimit); Assert.assertEquals(-2f, out.lowerTranslationM, 0f); Assert.assertEquals(3f, out.upperTranslationM, 0f); Assert.assertTrue(out.enableMotor); Assert.assertEquals(1.5f, out.motorSpeedMps, 0f); Assert.assertEquals(12f, out.maxMotorForce, 0f); }
    @Test public void copiesFrictionJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_FRICTION); PhysicsFrictionJointComponent c = w.getMapper(PhysicsFrictionJointComponent.class).create(src); c.maxForce = 8f; c.maxTorque = 9f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_FRICTION); Assert.assertTrue(w.getMapper(PhysicsFrictionJointComponent.class).has(clone)); PhysicsFrictionJointComponent out = w.getMapper(PhysicsFrictionJointComponent.class).get(clone); Assert.assertEquals(8f, out.maxForce, 0f); Assert.assertEquals(9f, out.maxTorque, 0f); }
    @Test public void copiesMotorJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_MOTOR); PhysicsMotorJointComponent c = w.getMapper(PhysicsMotorJointComponent.class).create(src); c.linearOffsetX = 2f; c.linearOffsetY = 3f; c.angularOffsetRad = 0.5f; c.maxForce = 10f; c.maxTorque = 11f; c.correctionFactor = 0.4f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_MOTOR); Assert.assertTrue(w.getMapper(PhysicsMotorJointComponent.class).has(clone)); PhysicsMotorJointComponent out = w.getMapper(PhysicsMotorJointComponent.class).get(clone); Assert.assertEquals(2f, out.linearOffsetX, 0f); Assert.assertEquals(3f, out.linearOffsetY, 0f); Assert.assertEquals(0.5f, out.angularOffsetRad, 0f); Assert.assertEquals(10f, out.maxForce, 0f); Assert.assertEquals(11f, out.maxTorque, 0f); Assert.assertEquals(0.4f, out.correctionFactor, 0f); }
    @Test public void copiesWeldJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_WELD); PhysicsWeldJointComponent c = w.getMapper(PhysicsWeldJointComponent.class).create(src); c.referenceAngleRad = 0.2f; c.frequencyHz = 5f; c.dampingRatio = 0.35f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_WELD); Assert.assertTrue(w.getMapper(PhysicsWeldJointComponent.class).has(clone)); PhysicsWeldJointComponent out = w.getMapper(PhysicsWeldJointComponent.class).get(clone); Assert.assertEquals(0.2f, out.referenceAngleRad, 0f); Assert.assertEquals(5f, out.frequencyHz, 0f); Assert.assertEquals(0.35f, out.dampingRatio, 0f); }
    @Test public void copiesPulleyJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_PULLEY); PhysicsPulleyJointComponent c = w.getMapper(PhysicsPulleyJointComponent.class).create(src); c.groundAx = -2f; c.groundAy = 4f; c.groundBx = 8f; c.groundBy = 9f; c.lengthAM = 3f; c.lengthBM = 7f; c.ratio = 1.6f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_PULLEY); Assert.assertTrue(w.getMapper(PhysicsPulleyJointComponent.class).has(clone)); PhysicsPulleyJointComponent out = w.getMapper(PhysicsPulleyJointComponent.class).get(clone); Assert.assertEquals(-2f, out.groundAx, 0f); Assert.assertEquals(4f, out.groundAy, 0f); Assert.assertEquals(8f, out.groundBx, 0f); Assert.assertEquals(9f, out.groundBy, 0f); Assert.assertEquals(3f, out.lengthAM, 0f); Assert.assertEquals(7f, out.lengthBM, 0f); Assert.assertEquals(1.6f, out.ratio, 0f); }
    @Test public void copiesGearJointComponents() { World w = world(); int src = w.create(); base(w, src, PhysicsJointComponent.TYPE_GEAR); PhysicsGearJointComponent c = w.getMapper(PhysicsGearJointComponent.class).create(src); c.joint1Eid = 21; c.joint2Eid = 22; c.ratio = 2.5f; int clone = clone(w, src); assertBase(w, clone, PhysicsJointComponent.TYPE_GEAR); Assert.assertTrue(w.getMapper(PhysicsGearJointComponent.class).has(clone)); PhysicsGearJointComponent out = w.getMapper(PhysicsGearJointComponent.class).get(clone); Assert.assertEquals(21, out.joint1Eid); Assert.assertEquals(22, out.joint2Eid); Assert.assertEquals(2.5f, out.ratio, 0f); }
    @Test public void copiesJointComponentsFromRealWheelJointEntity() { World w = world(); HistoryIdRegistry historyIds = new HistoryIdRegistry(); Box2dWorldService box2d = new Box2dWorldService(100f, new Vector2(0f, -9.81f)); try { PhysicsService physics = new PhysicsService(w, box2d); int a = body(w, historyIds, 0f, 0f); int b = body(w, historyIds, 5f, 2f); CreateJointCommand cmd = new CreateJointCommand(w, physics, historyIds, PhysicsJointComponent.TYPE_WHEEL, a, b, 1f, 2f); cmd.redo(); int src = cmd.getCreatedJointEntityId(); int clone = clone(w, src); PhysicsJointComponent srcBase = w.getMapper(PhysicsJointComponent.class).get(src); assertBase(w, clone, PhysicsJointComponent.TYPE_WHEEL, srcBase.aEid, srcBase.bEid, srcBase.anchorAx, srcBase.anchorAy, srcBase.anchorBx, srcBase.anchorBy, srcBase.collideConnected); PhysicsWheelJointComponent wheel = w.getMapper(PhysicsWheelJointComponent.class).get(src); PhysicsWheelJointComponent out = w.getMapper(PhysicsWheelJointComponent.class).get(clone); Assert.assertEquals(wheel.axisX, out.axisX, 0f); Assert.assertEquals(wheel.axisY, out.axisY, 0f); Assert.assertEquals(wheel.enableMotor, out.enableMotor); Assert.assertEquals(wheel.motorSpeedRad, out.motorSpeedRad, 0f); Assert.assertEquals(wheel.maxMotorTorque, out.maxMotorTorque, 0f); Assert.assertEquals(wheel.frequencyHz, out.frequencyHz, 0f); Assert.assertEquals(wheel.dampingRatio, out.dampingRatio, 0f); } finally { box2d.dispose(); } }

    private static World world() { return new World(new WorldConfiguration()); }
    private static void base(World world, int eid, int type) { PhysicsJointComponent base = world.getMapper(PhysicsJointComponent.class).create(eid); base.type = type; base.aEid = 11; base.bEid = 12; base.collideConnected = true; base.anchorAx = 0.1f; base.anchorAy = 0.2f; base.anchorBx = 0.3f; base.anchorBy = 0.4f; }
    private static int clone(World world, int src) { int clone = world.create(); GenericEntityInitializer i = new GenericEntityInitializer(world); i.syncFrom(src); i.init(clone); return clone; }
    private static void assertBase(World world, int eid, int type) { assertBase(world, eid, type, 11, 12, 0.1f, 0.2f, 0.3f, 0.4f, true); }
    private static void assertBase(World world, int eid, int type, int aEid, int bEid, float anchorAx, float anchorAy, float anchorBx, float anchorBy, boolean collideConnected) { Assert.assertTrue(world.getMapper(PhysicsJointComponent.class).has(eid)); PhysicsJointComponent out = world.getMapper(PhysicsJointComponent.class).get(eid); Assert.assertEquals(type, out.type); Assert.assertEquals(aEid, out.aEid); Assert.assertEquals(bEid, out.bEid); Assert.assertEquals(collideConnected, out.collideConnected); Assert.assertEquals(anchorAx, out.anchorAx, 0f); Assert.assertEquals(anchorAy, out.anchorAy, 0f); Assert.assertEquals(anchorBx, out.anchorBx, 0f); Assert.assertEquals(anchorBy, out.anchorBy, 0f); }
    private static int body(World world, HistoryIdRegistry historyIds, float x, float y) { int eid = world.create(); historyIds.ensureForEntity(eid); TransformComponent t = world.getMapper(TransformComponent.class).create(eid); t.x = x; t.y = y; PhysicsBodyComponent body = world.getMapper(PhysicsBodyComponent.class).create(eid); PhysicsService.initDefaultBody(body); PhysicsShapesComponent fixtures = world.getMapper(PhysicsShapesComponent.class).create(eid); fixtures.shapes.add(PhysicsService.createDefaultShape(eid + 1)); return eid; }
}
